SELECT status, DATE_TRUNC('MONTH', order_date) AS order_month, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_count, ROUND((100 * SUM(CASE WHEN channel = 'partner' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_partner, SUM(discount) AS total_discount FROM orders GROUP BY status, DATE_TRUNC('MONTH', order_date) HAVING SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) >= 53 ORDER BY completed_count DESC;
